          setHover(model.byBlock.has(b) ? b : null);
        }}
        onPointerLeave={() => setHover(null)}
      >
        {!model || !shown ? (
          <div className={styles.empty}>waiting for blocks…</div>
        ) : (
          <>
            <svg className={styles.svg} viewBox={`0 0 ${w} ${h}`} width={w} height={h} aria-hidden="true">
              <defs>

(e, i) => ({
