  return (
    <div className={styles.header}>
      <span className={styles.brand}>‖ Jev Trader</span>

      <span className={styles.block}>block {latest ? fmtInt(latest.block) : "-"}</span>

      <span className={styles.spacer} />

      {offline ? <span className={styles.offline}>{offline}</span> : null}

      <button
        type="button"
        className={styles.wallet}
        onClick={onCopy}
        disabled={!wallet}
        title={wallet ?? "no wallet, dry run"}
        aria-label={wallet ? `Copy wallet address ${wallet}` : "Dry run"}
      >
        {copied ? "copied" : wallet ? shortAddr(wallet) : "dry run"}
      </button>

      {model ? (
        <span
          className={styles.badge}
          style={{
            background: isJev
              ? "var(--badge-jev-bg)"
              : "var(--badge-standin-bg)",
            color: isJev ? "var(--badge-jev-fg)" : "var(--badge-standin-fg)",
          }}
        >
          {model}
        </span>
      ) : null}
    </div>
  );
}

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "connection":
      return state.connection === action.connection ? state : { ...state, connection: action.connection };

    case "snapshot": {
      const history = Array.isArray(action.history) ? action.history : [];
      const events = history.length > CAP ? history.slice(history.length - CAP) : history;
      let latSum = 0;
      let latCount = 0;
      for (const e of events) {
        const l = latencyOf(e);
        if (l !== null) {
          latSum += l;
          latCount++;
        }
      }
      return {
        meta: action.meta ?? state.meta,
        events,
        latest: events.length ? events[events.length - 1] : null,
        connection: "live",
        avgLatencyMs: avg(latSum, latCount),
        latSum,
        latCount,
      };
    }

    case "block": {
      const ev = action.event;
      if (!ev || typeof ev.block !== "number") return state;
      const prev = state.events;
      const last = prev.length ? prev[prev.length - 1] : null;

      // Dedupe: a re-sent block replaces the one we already have; a stale older block is dropped.
      if (last && ev.block <= last.block) {
        const idx = indexOfBlock(prev, ev.block);
        if (idx < 0) return state;
        const events = prev.slice();
        const old = events[idx];
        events[idx] = ev;
        let latSum = state.latSum;
        let latCount = state.latCount;
        const o = latencyOf(old);
        if (o !== null) {
          latSum -= o;
          latCount--;
        }
        const n = latencyOf(ev);
        if (n !== null) {
          latSum += n;
          latCount++;
        }
        return {
          ...state,
          events,
          latest: events[events.length - 1],
          avgLatencyMs: avg(latSum, latCount),
          latSum,
          latCount,
        };
      }

      let latSum = state.latSum;
      let latCount = state.latCount;
      const n = latencyOf(ev);
      if (n !== null) {
        latSum += n;
        latCount++;
      }
      let events = prev.concat(ev);
      if (events.length > CAP) {
        const drop = events.length - CAP;
        for (let i = 0; i < drop; i++) {
          const l = latencyOf(events[i]);
          if (l !== null) {
            latSum -= l;
            latCount--;
          }
        }
        events = events.slice(drop); // only ever slices once we are over the cap
      }
      return {
        ...state,
        events,
        latest: ev,
        avgLatencyMs: avg(latSum, latCount),
        latSum,
        latCount,
      };
    }

    case "fill": {
      const idx = indexOfBlock(state.events, action.block);
      if (idx < 0) return state;
      const events = state.events.slice();
      const updated: BlockEvent = { ...events[idx], fill: action.fill };
      events[idx] = updated;
      return {
        ...state,
        events,
        latest: idx === events.length - 1 ? updated : state.latest,
      };
    }

    case "quote": {
      const idx = indexOfBlock(state.events, action.block);
      if (idx < 0) return state;
      const events = state.events.slice();
      const updated: BlockEvent = { ...events[idx], quote: action.quote };
      events[idx] = updated;
      return {
        ...state,
        events,
        latest: idx === events.length - 1 ? updated : state.latest,
      };
    }

    default:
      return state;
  }
}
